table = {
    "device#001#20260101": {"metrics": {"temp": 21.5, "humidity": 40}},
    "device#001#20260102": {"metrics": {"temp": 22.1, "humidity": 38}},
    "device#002#20260101": {"metrics": {"temp": 19.8, "humidity": 55}},
}

def range_scan(table, prefix):
    return sorted(key for key in table if key.startswith(prefix))

def average_metric(table, keys, family, column):
    values = [table[key][family][column] for key in keys]
    return round(sum(values) / len(values), 2)

row_keys = range_scan(table, "device#001#")
print("Row keys for device#001:", row_keys)
print("Average temp:", average_metric(table, row_keys, "metrics", "temp"))
